import hashlib
import json

cache = {}

def create_cache_key(request):

    canonical = json.dumps(
        request,
        sort_keys=True,
        separators=(",", ":")
    )

    return hashlib.sha256(
        canonical.encode()
    ).hexdigest()

def get_response(request, llm_call):

    key = create_cache_key(request)

    if key in cache:
        print("CACHE HIT")
        return cache[key]

    print("CACHE MISS")

    response = llm_call(request)

    cache[key] = response

    return response

